ExecutorService pool = Executors.newFixedThreadPool(4);

for (int i = 0; i < 12; i++) {
	pool.submit(() -> {
		Thread.sleep(1000); // blocking I/O call (simulated)
		return null;
	});
}

pool.shutdown();
pool.awaitTermination(1, TimeUnit.MINUTES);
// 12 tasks / 4 threads = 3 rounds of 1 s = about 3 s

